#!/usr/bin/env python3
from pathlib import Path
import sys,html,base64,json
B=Path(__file__).resolve().parent;sys.path.insert(0,str(B/'render-support'))
from latex2mathml.converter import convert
esc=html.escape
def eq(s):return '<div class="eq">'+convert(s,display='block')+'</div>'
def mi(s):return convert(s)
def p(s):return '<p>'+s+'</p>'
def a(u,s):return '<a href="'+esc(u,quote=True)+'">'+esc(s)+'</a>'
def card(t,b,cls='good'):return '<article class="card '+cls+'"><h2>'+t+'</h2>'+b+'</article>'
F='https://arxiv.org/pdf/2608.01498v1';T='https://arxiv.org/pdf/1511.02032v2'
font=base64.b64encode((B/'render-support/fonts/STIXGeneral.ttf').read_bytes()).decode()
css='''@font-face{font-family:STIX;src:url(data:font/ttf;base64,FONT) format('truetype')}*{box-sizing:border-box}body{margin:0;padding:18px;background:#edf2f6;color:#193044;font:16px/1.55 system-ui,sans-serif}main{max-width:1100px;margin:auto}header,.card{background:white;border:1px solid #d3dfe7;border-radius:10px;padding:20px;margin:14px 0}h1{font-size:29px;line-height:1.2;margin:8px 0}h2{font-size:21px;line-height:1.25;margin:0 0 12px}.good{border-left:7px solid #287e60}.source{border-left:7px solid #7864a2}.note{border-left:7px solid #b38429}.eq{background:#f2f6fa;padding:12px 8px;margin:11px 0;overflow:auto;max-width:100%;border-radius:5px}math{font:20px STIX,serif}p math{font-size:18px}a{color:#145e98}code{font-size:13px;overflow-wrap:anywhere}p{margin:10px 0}.tag{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.meta{font-size:13px;color:#51687a}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:9px;border-bottom:1px solid #dce4ea;text-align:left;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere}footer{font-size:12px;color:#526575;margin:25px 0}@media(max-width:600px){body{padding:7px}header,.card{padding:14px}h1{font-size:25px}math{font-size:18px}}'''.replace('FONT',font)
out=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; font-src data:; img-src data:"><title>Positive first-Mertens bias: post-lock proof</title><style>'+css+'</style><main>']
out+=['<header><div class="tag">ROOT_POST_LOCK_SYNTHESIS · 20 November 2026</div><h1>A positive first-Mertens bias on the entire requested band</h1>'+eq(r'\mathrm{RH}\quad\Longrightarrow\quad A(x)-\log x-E>\frac{0.006}{\sqrt{x}}\qquad(e^{24}\le x\le10^{19}).')+eq(r'A(x)=\sum_{p\le x}\frac{\log p}{p},\qquad E=-\gamma-\sum_{p}\frac{\log p}{p(p-1)}.')+p('<strong>Written mathematics:</strong> complete from the precise published results displayed below. <strong>Lean:</strong> the entire new finite prime-power, convergence, Abel, integral and numerical argument is kernel checked; the original analytic formula and published computations remain five explicit source premises, alongside RH. The proof is not a formal proof of those publications or their computations.')+p('This is Root’s post-lock synthesis, with no independent-arm discovery credit. The existing published positive-bias data overlap the lower part of the band; no global priority, optimality or best-bound claim is made. Ordinary Lean mathematics is not called source-first program verification.')+'</header>']
body=p('Use '+mi(r'M=10^{19}')+', '+mi(r'y=\sqrt{x}')+', and the standard functions')+eq(r'C_A(x)=\sum_{n\le x}\frac{\Lambda(n)}n,\quad\psi(t)=\sum_{n\le t}\Lambda(n),\quad\vartheta(t)=\sum_{p\le t}\log p.')+p(a(F+'#page=1','BFKNW, (2)–(3), page 1')+' calls the prime sum '+mi(r'\Upsilon')+' and the von Mangoldt sum '+mi(r'\widetilde\psi')+'. Its '+a(F+'#page=2','constant identity (6), page 2')+' is')+eq(r'M^{\prime}=\gamma+\sum_{k=2}^{\infty}\sum_p\frac{\log p}{p^k},\qquad E=-M^{\prime}.')+p('In '+a('Definitions.lean','the actual Lean definitions')+', primes are filtered natural-number finsets up to the natural floor; '+mi(r'C_A')+' uses <code>ArithmeticFunction.vonMangoldt</code>, and '+mi(r'\psi,\vartheta')+' are the actual Mathlib Chebyshev functions. The full constant is a convergent sum over <em>all</em> primes. No numerical approximation to '+mi(r'E')+' is supplied or needed.')
out.append(card('1 · Definitions and normalization',body))
body=p(a(F+'#page=31','BFKNW Proposition 29(ii), equation (154), page 31')+' states, for every '+mi(r'x\ge2')+',')+eq(r'\left|C_A(x)-\log x+\gamma\right|\le\frac{|\psi(x)-x|}{x}+J_1(x)+\frac{\log(2\pi)}x.')+p('Here '+a(F+'#page=6','equation (29), page 6')+' defines the zero sum, with multiplicities, by')+eq(r'J_1(x)=\sum_{\rho=\beta+i\gamma}\frac{x^{\beta-1}}{|\gamma|^2}.')+p('The full-mass clause of '+a(F+'#page=19','Lemma 21, (85)–(90), page 19')+', specialized to its '+mi(r'm=1')+' coefficient, gives')+eq(r'2\sum_{\gamma>0}\frac1{\gamma^2}\le a_1=0.04620999.')+p('RH makes '+mi(r'\beta=1/2')+'; conjugate symmetry identifies the full ordinate sum with twice the positive sum. Consequently')+eq(r'J_1(x)\le\frac{0.04620999}{\sqrt{x}}\le\frac{0.0476}{\sqrt{x}},\qquad\log(2\pi)<2.')+p('The implementation deliberately permits the weaker coefficient 0.0476. '+a('SourceInterfaces.lean','Its literal source interfaces')+' define the actual nonreal zeta-zero domain, Mathlib meromorphic-order multiplicities, summability and '+mi(r'J_1')+'. RH factorization and the logarithm bound are proved there. The two original source predicates remain visible; the Platt/LMFDB zero data used by Lemma 21 are not recomputed. No new signed '+mi(r'F_0')+' or zero-spacing premise is introduced.')
out.append(card('2 · The original published weighted bound',body,'source'))
body=p(a(T+'#page=2','Büthe, Theorem 2, (1.5)–(1.7), page 2')+' provides exactly')+eq(r'|t-\psi(t)|\le0.94\sqrt t\quad(11<t\le M),')+eq(r't-\vartheta(t)\le1.95\sqrt t\quad(1423\le t\le M),\qquad t-\vartheta(t)>0.05\sqrt t\quad(1\le t\le M).')+p('These are numerical-source theorems, retained as publication inputs. Their three existing IEANTN conclusions are discharged into the consumer by '+a('IEANTNAdapters.lean','actual proved adapters')+'; the copied statement files are byte-pinned and freshly compiled. The final theorem never evaluates a Büthe bound above '+mi(r'M')+'.')
out.append(card('3 · The finite Büthe inputs',body,'source'))
body=p('Write the full prime correction as')+eq(r'P=\sum_p\frac{\log p}{p(p-1)},\qquad T_A(x)=P-(C_A(x)-A(x)).')+p('Equivalently, by the geometric series and absolute convergence,')+eq(r'T_A(x)=\sum_{\substack{p\ {\rm prime},\ k\ge2\\p^k>x}}\frac{\log p}{p^k}.')+p('<strong>The outer prime sum is unrestricted.</strong> Primes larger than '+mi(r'x')+' are included; dropping them would change the normalization constant. Convergence is proved in '+a('Convergence.lean','Lean')+': for primes at least two,')+eq(r'0\le\frac{\log p}{p(p-1)}\le\frac4{p^{3/2}},')+p('and the ordinary 3/2-series converges. The exact finite prime-power bijection from Mathlib then gives')+eq(r'C_A(x)-A(x)=\sum_{\substack{k\ge2,\ p^k\le x}}\frac{\log p}{p^k}\le\sum_{p\le y}\frac{\log p}{p(p-1)}.')+p('Subtract this finite upper bound from the full constant. Since '+mi(r'\log p/[p(p-1)]\ge\log p/p^2')+',')+eq(r'T_A(x)\ge S_2(y,M),\qquad S_2(y,M)=\sum_{y<p\le M}\frac{\log p}{p^2}.')+p(a('FiniteCorrection.lean','All of this finite-to-full transport is proved')+' for the actual finsets and von Mangoldt function; there is no assumed tail lower bound. Finally, the normalization is exactly')+eq(r'A(x)-\log x-E=\bigl(C_A(x)-\log x+\gamma\bigr)+T_A(x).')
out.append(card('4 · Keep the full prime-power correction',body))
body=p(a('AbelFinite.lean','Finite Abel summation in Lean')+' proves the ordinary-endpoint identity')+eq(r'S_2(y,M)=\frac{\vartheta(M)}{M^2}-\frac{\vartheta(y)}{y^2}+2\int_y^M\frac{\vartheta(t)}{t^3}\,dt.')+p('The relevant points satisfy '+mi(r'y>160000>1423')+'. On this entire finite interval, Büthe gives')+eq(r'\vartheta(y)\le y-0.05\sqrt y,\qquad\vartheta(t)\ge t-1.95\sqrt t\quad(y\le t\le M).')+p('The elementary definite integral is evaluated exactly:')+eq(r'2\int_y^M\frac{t-1.95\sqrt t}{t^3}\,dt=\frac2y-\frac2M-\frac{2.6}{y\sqrt y}+\frac{2.6}{M\sqrt M}.')+p('Combining the lower-endpoint allowance with the integral gives '+mi(r'2.55=2.6-0.05')+'. The upper endpoint '+mi(r'\vartheta(M)/M^2')+' and the last integral term are nonnegative. Thus')+eq(r'S_2(y,M)\ge\frac1y-\frac{2.55}{y\sqrt y}-\frac2M+\frac{2.6}{M\sqrt M}\ge\frac1y-\frac{2.55}{y\sqrt y}-\frac2M.')+p('This finite truncation loses one additional '+mi(r'1/M')+' compared with the initial sketch, which used a global theta lower bound. The requested final theorem still has sufficient slack. The implementation therefore needs neither a global theta estimate nor an improper-integral or limiting argument.')
out.append(card('5 · A finite Abel proof removes the global tail premise',body))
body=p('Throughout the closed requested band, the proved exponential bound '+mi(r'e^6>400')+' gives')+eq(r'\sqrt y=x^{1/4}\ge e^6>400,\qquad y>160000,\qquad \frac2y<\frac1{80000}.')+p('Also '+mi(r'y^2=x\le10^{19}<10^{20}')+', so '+mi(r'y<10^{10}')+' and')+eq(r'\frac yM<10^{-9}.')+p('The finite correction consequently satisfies')+eq(r'yT_A(x)\ge1-\frac{2.55}{\sqrt y}-\frac{2y}{M}>1-\frac{2.55}{400}-2\cdot10^{-9}=0.993624998.')+p('From the published weighted bound and Büthe’s pointwise psi bound,')+eq(r'y\left|C_A(x)-\log x+\gamma\right|\le0.94+0.0476+\frac2y<0.9876125.')+p('Combine the two signed inequalities with the exact normalization identity:')+eq(r'y\bigl(A(x)-\log x-E\bigr)>0.993624998-0.9876125=0.006012498>0.006.')+p('Division by the positive '+mi(r'y=\sqrt x')+' proves the claimed theorem, including both endpoints of '+mi(r'[e^{24},10^{19}]')+'. Every new elementary and numerical step in this proof is ordinary kernel-checked Lean; no floating-point acceptance or <code>native_decide</code> is used.')
out.append(card('6 · The strict margin survives all allowances',body))
body=p('The actual final integration theorem is <code>MertensPositive.first_mertens_positive_IEANTN</code>. Its exact remaining premises are:')+'<div class="scroll"><table><tr><th>Lean premise</th><th>Exact original correspondence</th><th>Evidence retained</th></tr><tr><td><code>SourceBFKNW154</code></td><td>Proposition 29(ii), (154), p.31</td><td>Cited analytic theorem; its proof is not formalized here</td></tr><tr><td><code>SourceBFKNW21</code></td><td>Lemma 21, m=1, (85)–(90), p.19</td><td>Convergent full ordinate sum and published numerical coefficient; zero computations not rerun</td></tr><tr><td><code>Buthe.v1.theorem_2_psi</code></td><td>Theorem 2, (1.5), p.2</td><td>Original finite computation</td></tr><tr><td><code>Buthe.v1.theorem_2_theta</code></td><td>Theorem 2, (1.6), p.2</td><td>Original finite computation</td></tr><tr><td><code>Buthe.v1.theorem_2_theta_lower</code></td><td>Theorem 2, (1.7), p.2</td><td>Original finite computation</td></tr><tr><td><code>RiemannHypothesis</code></td><td>Pinned Mathlib definition</td><td>Explicit unproved theorem parameter</td></tr></table></div>'+p('No convergence, prime-power correction, Abel identity, definite integral, new numerical constant or desired-sign statement remains as an additional premise. The generic '+a('SourceInterfaces.lean','mass-bound corollary')+' also accepts any separately proved summable full mass at most 0.0476, so a later xi-based argument can replace the numerical mass source without altering this consumer.')+p('The library is standalone pending Root’s integration; it registers no new Blueprint label or graph-engine machinery. '+a('THEOREM_CENSUS.json','The written-source theorem census')+' keys each declaration by file, name and line. '+a('SOURCE_MANIFEST.json','The exact source manifest')+' and '+a('COPIED_IEANTN_SOURCE_PINS.json','copied source pins')+' identify the complete compilation closure. '+a('Audit.lean','The actual axiom audit')+' checks all 27 new theorem declarations.')
out.append(card('7 · What the kernel proves and what remains cited',body,'source'))
body=p(a(F+'#page=50','BFKNW Table 13, page 50')+' already records stronger local positive-bias information on the overlap '+mi(r'[e^{24},e^{29}]')+'. The result here is a full-band corollary with an explicit kernel-checked consumer, not a claim to the best local bound or global priority. It is credited solely as post-lock Root synthesis, and does not alter either arm’s frozen outcome.')+p('Actual reuse: Mathlib’s <code>Chebyshev.sum_PrimePow_eq_sum_sum′</code>, geometric-series and p-series theorems, and its general Abel summation theorem are invoked by the new code. The finite Abel proof adapts the existing IEANTN <code>Solutions/CH2.v1/Section9Cor13Sum.lean</code> proof pattern to the new prime coefficient and squared reciprocal weight. Existing Büthe conclusions are consumed through three actual adapters. No old application proof objects are reused by fresh replay.')
out.append(card('Attribution and prior overlap',body,'note'))
out.append('<footer><p>Standalone static MathML with embedded licensed STIX font. No CDN, extension or external renderer is needed. Ordinary Lean proof checking is not source-first program verification; no C/C++/CUDA execution or official Comparator receipt is claimed.</p><details><summary>Embedded font license</summary><pre>'+esc((B/'render-support/fonts/LICENSE_STIX').read_text())+'</pre></details></footer></main></html>')
(B/'MERTENS_POSITIVE_PROOF.html').write_text(''.join(out));print('rendered',B/'MERTENS_POSITIVE_PROOF.html')
